// Generated by OrchestKit Claude Plugin
// Created: 2026-04-26 (M119 #1479)

/**
 * Session-scoped token accumulator state.
 *
 * Per-session estimator telemetry:
 *   - posttool/context-crossing-warn (writes estimatedTokens per tool result)
 *   - stop/goal-tracker + prompt/goal-tracker (read estimatedTokens as a
 *     recorded figure, never as a gate)
 *
 * `estimatedTokens` is a PARTIAL, ESTIMATED figure and nothing may gate on it
 * as if it were session context (#3321 claim 2). Its writer sees only
 * `Read|Grep|Glob|WebFetch|WebSearch` results and converts them with a
 * characters-per-token heuristic, so it is neither the whole context nor a
 * measurement of it. Anything comparing against the context window must use
 * `lib/transcript-context.ts`, which reads CC's own reported usage.
 *
 * The second writer, subagent-stop/unified-dispatcher, was removed with the
 * cache-heat machinery in #3427: CC's SubagentStop payload carries neither
 * cache token field, so it never wrote anything. The single remaining writer
 * does read-modify-write through atomicWriteSync; token counts are
 * incremental so a lost update costs one tool result of telemetry.
 */

import { existsSync, readFileSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { atomicWriteSync } from './atomic-write.js';
import { getContextWindowTokens } from './context-window.js';
import type { ContentKind } from './token-estimator.js';

export interface AccumState {
  /** Estimated input tokens added by tool results this session. */
  estimatedTokens: number;
  /** Sum of cache_read_input_tokens across SubagentStop events this session. */
  cacheReadTokens: number;
  /** Sum of cache_creation_input_tokens across SubagentStop events this session. */
  cacheCreationTokens: number;
  /** Per-threshold one-shot fire flags ({"160000": true, ...}). */
  crossings: Record<string, boolean>;
  /** ISO timestamp of first state write — used to compute session age. */
  firstSeenAt: string;
  /** ISO timestamp of last state write. */
  updatedAt: string;
  lastToolName?: string;
  /** Counts per content kind (debug aid for #1478 estimator accuracy). */
  kindCounts?: Partial<Record<ContentKind, number>>;
  /** Image responses observed (model-side tokenization is separate). */
  imageResponses?: number;
}

export function getStateFile(projectDir: string, sessionId: string): string {
  return join(projectDir, '.claude', 'state', `session-${sessionId}-token-accum.json`);
}

function freshState(): AccumState {
  const now = new Date().toISOString();
  return {
    estimatedTokens: 0,
    cacheReadTokens: 0,
    cacheCreationTokens: 0,
    crossings: {},
    firstSeenAt: now,
    updatedAt: now,
    kindCounts: {},
    imageResponses: 0,
  };
}

export function loadAccumState(projectDir: string, sessionId: string): AccumState {
  const path = getStateFile(projectDir, sessionId);
  if (!existsSync(path)) return freshState();
  try {
    const parsed = JSON.parse(readFileSync(path, 'utf8')) as Partial<AccumState>;
    const fresh = freshState();
    return {
      estimatedTokens: Number(parsed.estimatedTokens) || 0,
      cacheReadTokens: Number(parsed.cacheReadTokens) || 0,
      cacheCreationTokens: Number(parsed.cacheCreationTokens) || 0,
      crossings:
        parsed.crossings && typeof parsed.crossings === 'object' ? parsed.crossings : {},
      firstSeenAt: parsed.firstSeenAt || fresh.firstSeenAt,
      updatedAt: parsed.updatedAt || fresh.updatedAt,
      lastToolName: parsed.lastToolName,
      kindCounts:
        parsed.kindCounts && typeof parsed.kindCounts === 'object' ? parsed.kindCounts : {},
      imageResponses: Number(parsed.imageResponses) || 0,
    };
  } catch {
    return freshState();
  }
}

export function saveAccumState(
  projectDir: string,
  sessionId: string,
  state: AccumState,
): void {
  const path = getStateFile(projectDir, sessionId);
  try {
    mkdirSync(dirname(path), { recursive: true });
    atomicWriteSync(path, JSON.stringify(state, null, 2));
  } catch {
    // best-effort — telemetry must never break the hook chain
  }
}

// evaluateCacheHeat and the CacheHeat type were DELETED (#3321 claim 3): their
// input, cacheReadTokens, never had a live writer. CC's SubagentStop payload
// builder (verified against the 2.1.227 binary) sends neither
// cache_read_input_tokens nor cache_creation_input_tokens, so the sole
// writer's zero-check early return was always taken, and 0 of 93 real state
// files ever held a non-zero value. The two fields stay in AccumState so
// existing state files keep parsing, but nothing reads or writes them.

/**
 * Load state for a session. Returns null when no real accumulator data exists
 * (fresh state with zero tokens + no crossings) — callers can treat null as
 * "no signal yet, don't gate on it".
 */
export function loadAccumStateOrNull(projectDir: string, sessionId: string): AccumState | null {
  try {
    const state = loadAccumState(projectDir, sessionId);
    if (state.estimatedTokens === 0 && Object.keys(state.crossings).length === 0) {
      return null;
    }
    return state;
  } catch {
    return null;
  }
}

const DEFAULT_IMMINENT_PCT = 0.85;

export function readImminentPct(): number {
  const raw = process.env.ORK_CTX_IMMINENT_PCT;
  if (!raw) return DEFAULT_IMMINENT_PCT;
  const parsed = parseFloat(raw);
  if (!Number.isFinite(parsed) || parsed <= 0 || parsed >= 1) return DEFAULT_IMMINENT_PCT;
  return parsed;
}

/** Absolute token count at which the imminent zone starts. */
export function imminentThreshold(): number {
  return Math.round(getContextWindowTokens() * readImminentPct());
}

/**
 * #1480, corrected by #3321 claim 2 — true when MEASURED context occupancy has
 * crossed the imminent zone (default 85% of `CLAUDE_MAX_CONTEXT`).
 *
 * This used to take `AccumState` and compare `estimatedTokens` against the
 * threshold. That comparison was a unit mismatch, not a mis-calibration: the
 * accumulator's only writer is registered under matcher
 * `Read|Grep|Glob|WebFetch|WebSearch`, so its numerator excluded Bash, Edit,
 * Write, agent results, MCP and every conversation turn, while the threshold
 * was a whole-window figure. The gate returned false on 2,246 of 2,246
 * recorded PreCompact invocations. See lib/transcript-context.ts for the
 * measured source that replaces it.
 *
 * Returns false when there is no measurement, so an unreadable transcript
 * fails OPEN (compaction proceeds) rather than blocking on a guess.
 */
export function isInImminentZone(measuredContextTokens: number | null): boolean {
  if (measuredContextTokens === null || measuredContextTokens <= 0) return false;
  return measuredContextTokens >= imminentThreshold();
}
